package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
/** Reuses real-MySQL inventory fixtures and also runs their existing compatibility tests. */
class JdbcInviteRewardPoliciesTest extends JdbcCouponInventoryTest {
 InviteRewardPolicies policies;
 @BeforeEach void policies(){jdbc.update("DELETE FROM invite_reward_policy");jdbc.update("UPDATE operator_account SET can_invite=1 WHERE id=1");policies=new InviteRewardPolicies(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())),coupons);}
 long rewardCoupon(int n){long id=publish(n);coupons.pool(operator,id,key(),json.createObjectNode().put("expected_pool_revision",0).put("selected",true));return id;}
 ObjectNode policy(long id,String scope){var b=json.createObjectNode().put("scope",scope).put("source_note","用户确认规则与合成券池").put("valid_from",clock.value.toString()).put("valid_to",clock.value.plusSeconds(1800).toString()).put("invitee_coupon_id",id).put("invitee_publication_revision",2);if(scope.equals("OWNER"))b.put("inviter_coupon_id",id).put("inviter_publication_revision",2);else b.putNull("inviter_coupon_id").putNull("inviter_publication_revision");return b;}
 long draft(long coupon,String scope){var b=policy(coupon,scope);InvitePolicyInput.draft(b.toString(),false);return policies.create(operator,key(),b).path("data").path("id").longValue();}
 void activate(long id){policies.status(operator,id,key(),json.createObjectNode().put("expected_revision",1).put("status","PUBLISHED"));}
 @Test void unconfiguredIsUnknownAndPublishedSnapshotDoesNotIssueOrConsumeStock(){assertEquals("UNKNOWN",policies.current(owner,"OWNER").get("state"));long c=rewardCoupon(2),id=draft(c,"OWNER");activate(id);assertEquals("CONFIGURED",policies.current(owner,"OWNER").get("state"));assertEquals(0,count("coupon_issue"));assertEquals(0,count("user_coupon"));assertEquals(0,jdbc.queryForObject("SELECT issued_quantity FROM coupon WHERE id=?",Integer.class,c));var r=policies.status(operator,id,key(),json.createObjectNode().put("expected_revision",2).put("status","STOPPED"));assertEquals("STOPPED",r.path("data").path("status").textValue());assertEquals("UNKNOWN",policies.current(owner,"OWNER").get("state"));assertEquals(409,code(()->activate(id)));}
 @Test void separatePermissionCannotBorrowCouponOrReviewRightsAndReplayRevocationWorks(){long c=rewardCoupon(2);var b=policy(c,"STAFF");jdbc.update("UPDATE operator_account SET can_invite=0,can_coupon=1,can_review=1 WHERE id=1");assertEquals(403,code(()->policies.create(operator,key(),b)));jdbc.update("UPDATE operator_account SET can_invite=1 WHERE id=1");String k=key();policies.create(operator,k,b);jdbc.update("UPDATE operator_account SET can_invite=0 WHERE id=1");assertEquals(403,code(()->policies.create(operator,k,b)));}
 @Test void ownerAndStaffRulesAreIndependentWithOnePublishedEach(){long c=rewardCoupon(2),a=draft(c,"OWNER"),b=draft(c,"OWNER"),s=draft(c,"STAFF");activate(a);activate(s);assertEquals(409,code(()->activate(b)));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM invite_reward_policy WHERE status='PUBLISHED'",Integer.class));}
 @Test void twoOperatorsConcurrentPublishHaveExactlyOneWinner()throws Exception{long c=rewardCoupon(2),a=draft(c,"OWNER"),b=draft(c,"OWNER");jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_invite) VALUES(2,'synthetic-invite-peer','unused','13800000001',1)");var op2=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),java.time.Instant.now().plusSeconds(600));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var one=pool.submit(()->{start.await();try{activate(a);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var two=pool.submit(()->{start.await();try{policies.status(op2,b,key(),json.createObjectNode().put("expected_revision",1).put("status","PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});start.countDown();var result=new ArrayList<>(List.of(one.get(30,TimeUnit.SECONDS),two.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertEquals(List.of(200,409),result);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM invite_reward_policy WHERE status='PUBLISHED'",Integer.class));}finally{pool.shutdownNow();}}
 @Test void sourceRevisionPoolAndValidityAreCheckedAgainOnPublishing(){long c=rewardCoupon(2),id=draft(c,"OWNER");jdbc.update("UPDATE coupon_source SET pool_selected=0 WHERE coupon_id=?",c);assertEquals(409,code(()->activate(id)));jdbc.update("UPDATE coupon_source SET pool_selected=1 WHERE coupon_id=?",c);var b=policy(c,"OWNER").put("invitee_publication_revision",3);assertEquals(409,code(()->policies.create(operator,key(),b)));final var invalid=policy(c,"OWNER").put("valid_to",clock.value.plusSeconds(3601).toString());assertEquals(409,code(()->policies.create(operator,key(),invalid)));}
 @Test void publishedTermsCannotBeEditedAndExpiryOrDisabledIssuerIsExplicit(){long c=rewardCoupon(2),id=draft(c,"OWNER");activate(id);var b=policy(c,"OWNER").put("expected_revision",2);assertEquals(409,code(()->policies.update(operator,id,key(),b)));jdbc.update("UPDATE merchant SET status=0 WHERE id=1");assertEquals("SOURCE_UNAVAILABLE",policies.current(owner,"OWNER").get("state"));clock.value=clock.value.plusSeconds(1800);assertEquals("EXPIRED",policies.current(owner,"OWNER").get("state"));}
 @Test void draftsHaveVersionCasAndStableSameKeyReceipt(){long c=rewardCoupon(2);String k=key();var b=policy(c,"OWNER");var first=policies.create(operator,k,b);assertEquals(first,policies.create(operator,k,b));long id=first.path("data").path("id").longValue();var next=policy(c,"STAFF").put("expected_revision",1);policies.update(operator,id,key(),next);assertEquals(409,code(()->policies.update(operator,id,key(),next)));assertEquals(1,count("invite_reward_policy"));}
 @Test void policyAuditFailureRollsBackAndRetriesWithoutIssuing(){long c=rewardCoupon(2);jdbc.execute("CREATE TRIGGER fail_coupon_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");assertEquals(503,code(()->policies.create(operator,key(),policy(c,"OWNER"))));assertEquals(0,count("invite_reward_policy"));assertEquals(0,count("coupon_issue"));}
 @Test void strictPolicyBodiesRejectStaffBeneficiaryAndProofOverrides(){var b=policy(1,"STAFF");assertDoesNotThrow(()->InvitePolicyInput.draft(b.toString(),false));b.put("inviter_coupon_id",1);assertThrows(Exception.class,()->InvitePolicyInput.draft(b.toString(),false));assertThrows(Exception.class,()->InvitePolicyInput.draft(policy(1,"OWNER").put("new_user",true).toString(),false));assertThrows(Exception.class,()->InvitePolicyInput.status("{\"status\":\"PUBLISHED\",\"expected_revision\":1}{}"));}
}
